import{_ as a,o as s,c as n,ag as i}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Memory Areas — Heap, Stack, Metaspace, Code Cache","description":"","frontmatter":{},"headers":[],"relativePath":"java/foundations/memory_areas/MemoryAreas.md","filePath":"java/foundations/memory_areas/MemoryAreas.md"}'),t={name:"java/foundations/memory_areas/MemoryAreas.md"};function o(r,e,p,l,h,c){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="memory-areas-—-heap-stack-metaspace-code-cache" tabindex="-1">Memory Areas — Heap, Stack, Metaspace, Code Cache <a class="header-anchor" href="#memory-areas-—-heap-stack-metaspace-code-cache" aria-label="Permalink to &quot;Memory Areas — Heap, Stack, Metaspace, Code Cache&quot;">​</a></h1><hr><h2 id="the-big-picture" tabindex="-1">The big picture <a class="header-anchor" href="#the-big-picture" aria-label="Permalink to &quot;The big picture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JVM Process</span></span>
<span class="line"><span>├── Heap              — shared across all threads</span></span>
<span class="line"><span>│   ├── Young Generation  (~1/3 of heap by default)</span></span>
<span class="line"><span>│   │   ├── Eden          (~80% of Young Gen)</span></span>
<span class="line"><span>│   │   ├── Survivor S0   (~10% of Young Gen)</span></span>
<span class="line"><span>│   │   └── Survivor S1   (~10% of Young Gen)</span></span>
<span class="line"><span>│   ├── Old Generation    (~2/3 of heap by default)</span></span>
<span class="line"><span>│   └── String Pool       — inside heap since Java 7</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Metaspace         — native memory (outside heap), since Java 8</span></span>
<span class="line"><span>├── Code Cache        — JIT-compiled native code, native memory</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Per-thread areas (one per thread)</span></span>
<span class="line"><span>    ├── Stack</span></span>
<span class="line"><span>    ├── PC Register</span></span>
<span class="line"><span>    └── Native Method Stack</span></span></code></pre></div><hr><h2 id="heap" tabindex="-1">Heap <a class="header-anchor" href="#heap" aria-label="Permalink to &quot;Heap&quot;">​</a></h2><p>Objects live here. All <code>new</code> expressions allocate here. Shared across threads.</p><h3 id="young-generation-—-how-minor-gc-works-ping-pong" tabindex="-1">Young Generation — how Minor GC works (ping-pong) <a class="header-anchor" href="#young-generation-—-how-minor-gc-works-ping-pong" aria-label="Permalink to &quot;Young Generation — how Minor GC works (ping-pong)&quot;">​</a></h3><p>New objects start in <strong>Eden</strong>. When Eden fills up, a <strong>Minor GC</strong> runs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before GC:  Eden (full)   S0 (active, has survivors)   S1 (empty)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Minor GC:</span></span>
<span class="line"><span>  1. Scan Eden + S0 for live objects</span></span>
<span class="line"><span>  2. Copy them all into S1</span></span>
<span class="line"><span>  3. Eden + S0 are now empty</span></span>
<span class="line"><span>  4. S0 and S1 swap roles — S1 is now active, S0 is empty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Next Minor GC: same thing in reverse — live objects from Eden + S1 copied into S0</span></span></code></pre></div><p>Why two Survivor spaces? Copying GC needs a clean destination — you can&#39;t copy objects in place.</p><p><strong>Age counter:</strong> each survived copy ticks the object&#39;s age up by 1. At age 15 (default tenuring threshold) it gets <strong>promoted</strong> to Old Generation instead of copied again.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Minor GC 1:  Eden → S0  (age=1)</span></span>
<span class="line"><span>Minor GC 2:  S0   → S1  (age=2)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Minor GC 15: S?   → Old Gen  (promoted)</span></span></code></pre></div><p>Minor GC is cheap — only touches Young Gen, runs frequently.</p><h3 id="old-generation-tenured" tabindex="-1">Old Generation (Tenured) <a class="header-anchor" href="#old-generation-tenured" aria-label="Permalink to &quot;Old Generation (Tenured)&quot;">​</a></h3><p>Long-lived promoted objects live here. When Old Gen fills up, a <strong>Major GC (Full GC)</strong> runs — scans the entire heap, expensive, noticeable pause. If Full GC still can&#39;t free space → <code>OutOfMemoryError: Java heap space</code>.</p><p><strong>Default ratio:</strong> Young Gen = ~1/3 of heap (<code>-XX:NewRatio=2</code> means Old:Young = 2:1). On a 3 GB heap: ~1 GB Young, ~2 GB Old. Tunable for high-churn apps.</p><h3 id="string-pool-inside-heap-since-java-7" tabindex="-1">String Pool (inside heap since Java 7) <a class="header-anchor" href="#string-pool-inside-heap-since-java-7" aria-label="Permalink to &quot;String Pool (inside heap since Java 7)&quot;">​</a></h3><p>String literals and <code>.intern()</code> calls resolve to the pool. Same content → same object.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true — same pool object</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// false — c is a new heap object</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">equals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(c);         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true — same content</span></span></code></pre></div><p><strong>Why it moved from PermGen to heap (Java 7):</strong></p><ol><li>In PermGen, interned strings were never GC&#39;d — pool could fill up causing OOM with no recovery.</li><li>PermGen was fixed-size and hard to tune; the heap is already dynamically managed.</li></ol><p>Since Java 7, interned strings with no references get collected normally.</p><hr><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><p>Each thread has its own stack. Holds <strong>frames</strong> — one per active method call.</p><p><strong>A frame contains:</strong></p><ul><li>Local variables (method parameters + declared locals)</li><li>Operand stack (workspace for bytecode instructions)</li><li>Reference to the runtime constant pool</li></ul><p>Frame pushed on method call, popped on return. <strong>Primitives and references live on the stack; the objects they point to are on the heap.</strong> Frame disappears instantly on return — no GC needed for stack memory.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> foo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// value 42 on the stack frame</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Person p </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Person</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// reference p on stack; Person object on heap</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// frame popped → x and p gone immediately</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Person object on heap → GC&#39;d whenever nothing points to it</span></span></code></pre></div><p><code>StackOverflowError</code> = thread&#39;s stack is full (usually unbounded recursion).</p><hr><h2 id="metaspace" tabindex="-1">Metaspace <a class="header-anchor" href="#metaspace" aria-label="Permalink to &quot;Metaspace&quot;">​</a></h2><p>Holds <strong>class metadata</strong> — field names, method signatures, bytecode, constant pool, annotations. The <em>blueprint</em> of every loaded class.</p><p>Replaced PermGen in Java 8:</p><ul><li>PermGen: fixed-size inside the JVM heap → <code>OutOfMemoryError: PermGen space</code></li><li>Metaspace: native memory (outside heap) → auto-grows by default</li></ul><p><strong>Static field values</strong> are NOT in Metaspace — they live on the heap (on the <code>Class</code> object). Only the structure (that a field named <code>count</code> of type <code>int</code> exists) is in Metaspace.</p><h3 id="when-metaspace-becomes-a-problem-—-dynamic-class-generation" tabindex="-1">When Metaspace becomes a problem — dynamic class generation <a class="header-anchor" href="#when-metaspace-becomes-a-problem-—-dynamic-class-generation" aria-label="Permalink to &quot;When Metaspace becomes a problem — dynamic class generation&quot;">​</a></h3><p>Every new class blueprint grows Metaspace. In normal apps classes load at startup and stabilize, but some patterns generate classes continuously at runtime:</p><ul><li><strong>Groovy/scripting engines</strong> — each unique script text compiles into a new class blueprint. 1000 different scripts = 1000 blueprints in Metaspace.</li><li><strong>Frameworks generating runtime proxies without caching</strong> — Spring AOP generates one proxy class per service at startup (fine). A framework generating a fresh proxy per request without caching produces unbounded blueprints.</li></ul><p><strong>Why blueprints don&#39;t get cleaned up:</strong> a class is only unloaded when its ClassLoader is GC&#39;d. In server apps the ClassLoader lives forever → blueprints accumulate permanently.</p><p><strong>Fix:</strong> cache compiled scripts/proxies so the same input reuses the existing blueprint. Cap with <code>-XX:MaxMetaspaceSize=256m</code> for early warning instead of silently consuming all native memory.</p><hr><h2 id="code-cache" tabindex="-1">Code Cache <a class="header-anchor" href="#code-cache" aria-label="Permalink to &quot;Code Cache&quot;">​</a></h2><p>JVM starts by interpreting bytecode line by line (slow). As it runs, the JIT compiler translates <strong>hot methods</strong> (called frequently) into native machine code, stored in the <strong>Code Cache</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>First ~1000 calls:  JVM interprets placeOrder() — slow</span></span>
<span class="line"><span>JIT compiles it:    native machine code stored in Code Cache</span></span>
<span class="line"><span>All future calls:   CPU runs machine code directly — fast</span></span></code></pre></div><p>Default size: ~240 MB (<code>-XX:ReservedCodeCacheSize</code>). If full, JVM stops JIT-compiling new methods and falls back to interpretation — severe performance degradation. You&#39;ll see: <code>CodeCache is full. Compiler has been disabled</code>.</p><p>Rarely an issue for typical Spring Boot services. Can hit very large apps or apps with heavy reflection.</p><hr><h2 id="native-methods-and-native-method-stack" tabindex="-1">Native Methods and Native Method Stack <a class="header-anchor" href="#native-methods-and-native-method-stack" aria-label="Permalink to &quot;Native Methods and Native Method Stack&quot;">​</a></h2><p>Some Java methods are implemented in C/C++ — declared with the <code>native</code> keyword, no body:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> native</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> long</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> currentTimeMillis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// implemented in C, in the JVM itself</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> native</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> arraycopy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(...);</span></span></code></pre></div><p>Java can&#39;t directly access the OS (file system, clock, hardware) — it&#39;s isolated inside the JVM. Native methods are the escape hatch: they drop out of the JVM and call the OS directly via <strong>JNI (Java Native Interface)</strong>.</p><p>Daily examples: <code>System.currentTimeMillis()</code>, <code>Thread.sleep()</code>, default <code>Object.hashCode()</code>, all file I/O under the hood.</p><p><strong>Native Method Stack</strong> — like the Java stack, but tracks C/C++ call frames during native method execution. One per thread, separate because C and Java have different calling conventions.</p><hr><h2 id="real-world-config-from-prod-services" tabindex="-1">Real-world config (from prod services) <a class="header-anchor" href="#real-world-config-from-prod-services" aria-label="Permalink to &quot;Real-world config (from prod services)&quot;">​</a></h2><p>All services use G1GC (<code>-XX:+UseG1GC</code>). Three heap strategies seen in practice:</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Flag</th><th>Used when</th></tr></thead><tbody><tr><td>Dynamic % of container RAM</td><td><code>-XX:MaxRAMPercentage=90</code></td><td>Pod size varies — no hardcoded <code>-Xmx</code> needed</td></tr><tr><td>Aggressive heap shrinking</td><td><code>-XX:MinHeapFreeRatio=5 -XX:MaxHeapFreeRatio=20</code></td><td>Bursty traffic — grow during spikes, shrink back to save memory</td></tr><tr><td>Fixed heap</td><td><code>-Xmx1512m -Xms256m</code></td><td>Cron jobs with known memory profile</td></tr></tbody></table><p>No Metaspace or Code Cache flags set — G1GC sizes regions dynamically and defaults suffice for typical services.</p><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Heap vs stack — one-line difference?</strong> A. Heap is shared across threads, holds objects. Stack is per-thread, holds frames (locals + references), cleared instantly on method return.</p><p><strong>Q. Why two Survivor spaces?</strong> A. Copying GC needs a clean destination — one is always source, one is always target, they swap each GC cycle.</p><p><strong>Q. How does an object get promoted to Old Gen?</strong> A. Survives 15 Minor GC cycles (age threshold) or is too large for Survivor space.</p><p><strong>Q. Why did the string pool move to heap in Java 7?</strong> A. PermGen strings were never GC&#39;d → OOM with no recovery. Heap strings are GC&#39;d normally.</p><p><strong>Q. Why did Metaspace replace PermGen?</strong> A. PermGen was fixed-size → easy to exhaust. Metaspace uses native memory and auto-grows.</p><p><strong>Q. What causes <code>OutOfMemoryError: Metaspace</code>?</strong> A. Too many class blueprints loaded — usually dynamic class generation (Groovy scripts, uncached proxies) without caching or a size cap.</p><p><strong>Q. What is the Code Cache?</strong> A. Native memory where JIT-compiled machine code lives. If full, JVM falls back to interpretation — severe perf hit.</p><p><strong>Q. What are native methods?</strong> A. Java methods implemented in C/C++, declared with <code>native</code>. Used for OS-level operations (clock, file I/O, hardware) that the JVM can&#39;t do directly. Bridge is JNI.</p>`,70)])])}const k=a(t,[["render",o]]);export{g as __pageData,k as default};
